package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class DecisionReauthenticationAcceptance {
 static Map<String,Object> definition(){return map("version",0,"label","Confirmed decisions","prefix","DECISION","fields",map("short_description","Summary","state","State"),"states",map("new","New","done","Done"),"flow",map("new",List.of("done")),"transition_rules",map("done",map("min_approvals",1,"reauthenticate",true)));}
 static String create(WorkflowSupport h,String table) throws Exception{return object(parsed(h.json("POST","/api/now/table/"+table,map("short_description","Decision needing review"),auth("admin"))).get("result")).get("sys_id").toString();}
 static Map<String,Object> proposal(String reviewer){return map("expected_revision",0,"approver",reviewer,"target_state","done","reason","Review the complete proposal");}
 static String request(WorkflowSupport h,String path,String reviewer) throws Exception{var response=h.json("POST",path,proposal(reviewer),auth("admin"));assertEquals(201,response.statusCode(),html(response));return object(parsed(response).get("result")).get("approval_id").toString();}
 static void revokedSession(WorkflowSupport h) throws Exception {
  String table="u_confirm_"+id();h.account("RevokedDecisionReviewer","agent");String approval,record;
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Configuration.install(db,ContactFieldsAcceptance.bundle(table,definition()),actor,false);record=PlatformFoundationTest.record(db,table,"Revoked confirmation");approval=Approvals.request(db,table,record,db.one("SELECT * FROM os_user WHERE user_id=?",actor),proposal("RevokedDecisionReviewer")).get("approval_id").toString();db.connection.commit();}
  String csrf=h.login("RevokedDecisionReviewer");
  try {
   try(var db=h.store.open()){
    if(db.postgres){db.update("CREATE FUNCTION test_reauth_revocation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.mechanism='approval-review' AND NEW.outcome='succeeded' THEN DELETE FROM os_browser_session WHERE user_id=NEW.user_id; END IF; RETURN NEW; END $$");db.update("CREATE TRIGGER test_reauth_revocation AFTER INSERT ON os_auth_event FOR EACH ROW EXECUTE FUNCTION test_reauth_revocation()");}
    else db.update("CREATE TRIGGER test_reauth_revocation AFTER INSERT ON os_auth_event WHEN NEW.mechanism='approval-review' AND NEW.outcome='succeeded' BEGIN DELETE FROM os_browser_session WHERE user_id=NEW.user_id; END");db.connection.commit();
   }
   var response=h.form("/record/"+table+"/"+record+"/approvals/"+approval+"/decision",map("csrf",csrf,"decision","approved","comment","","current_password",PASSWORD),null);assertEquals(401,response.statusCode(),html(response));assertTrue(html(response).contains("Browser session ended"));
   try(var db=h.store.open()){assertEquals("requested",db.one("SELECT status FROM os_approval WHERE approval_id=?",approval).get("status"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action='approval.decided'",record));assertEquals(1,db.count("SELECT COUNT(*) FROM os_auth_event WHERE mechanism='approval-review' AND outcome='succeeded'"));}
  }finally{try(var db=h.store.open()){db.update(db.postgres?"DROP TRIGGER IF EXISTS test_reauth_revocation ON os_auth_event":"DROP TRIGGER IF EXISTS test_reauth_revocation");if(db.postgres)db.update("DROP FUNCTION IF EXISTS test_reauth_revocation()");db.update("DELETE FROM os_record WHERE \"table\"=?",table);db.update("DELETE FROM os_schema WHERE name=?",table);db.connection.commit();}}
 }
 static void run(WorkflowSupport h) throws Exception {String table="u_decision_"+id();h.account("ConfirmReviewer","agent");h.account("OtherConfirmReviewer","agent");h.account("LimitedConfirmReviewer","agent");var d=definition();var bundle=ContactFieldsAcceptance.bundle(table,d);var policy=object(object(d.get("transition_rules")).get("done"));
  try{
   policy.put("reauthenticate","yes");assertEquals(400,h.json("POST",ConfigurationAcceptance.API+"?dry_run=false",bundle,auth("admin")).statusCode());policy.put("reauthenticate",true);assertEquals(200,h.json("POST",ConfigurationAcceptance.API+"?dry_run=false",bundle,auth("admin")).statusCode());String record=create(h,table),path="/api/openservice/records/"+table+"/"+record+"/approvals",approval=request(h,path,"ConfirmReviewer"),decision=path+"/"+approval+"/decision";var body=map("decision","approved","comment","");
   assertEquals(400,h.json("POST",decision,body,auth("ConfirmReviewer")).statusCode());body.put("current_password","incorrect password");assertEquals(400,h.json("POST",decision,body,auth("ConfirmReviewer")).statusCode());try(var db=h.store.open()){assertEquals("requested",db.one("SELECT status FROM os_approval WHERE approval_id=?",approval).get("status"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_auth_event WHERE mechanism='approval-review' AND outcome='failed'"));}
   for(Object invalid:List.of(3,"x".repeat(1025))){body.put("current_password",invalid);assertEquals(400,h.json("POST",decision,body,auth("ConfirmReviewer")).statusCode());}body.put("current_password",PASSWORD);body.put("extra",true);assertEquals(400,h.json("POST",decision,body,auth("ConfirmReviewer")).statusCode());body.remove("extra");assertEquals(403,h.json("POST",decision,body,auth("OtherConfirmReviewer")).statusCode());
   var saved=h.json("POST",decision,body,auth("ConfirmReviewer"));assertEquals(200,saved.statusCode(),html(saved));assertEquals(true,object(parsed(saved).get("result")).get("requires_reauthentication"));assertEquals(409,h.json("POST",decision,body,auth("ConfirmReviewer")).statusCode());assertFalse(html(saved).contains(PASSWORD));
   try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);assertEquals("new",object(Service.record(db,table,record).get("data")).get("state"));var audit=db.one("SELECT detail FROM os_event WHERE record_id=? AND action='approval.decided'",record);assertEquals(true,object(audit.get("detail")).get("reauthenticated"));assertFalse(audit.toString().contains(PASSWORD));}
   assertEquals(200,h.json("PATCH","/api/now/table/"+table+"/"+record,map("state","done"),auth("admin")).statusCode());
   String second=create(h,table),secondPath="/api/openservice/records/"+table+"/"+second+"/approvals",secondApproval=request(h,secondPath,"ConfirmReviewer");assertEquals(200,h.json("POST",secondPath+"/"+secondApproval+"/decision",map("decision","rejected","comment","Needs correction","current_password",PASSWORD),auth("ConfirmReviewer")).statusCode());
   String third=create(h,table),thirdPath="/api/openservice/records/"+table+"/"+third+"/approvals",thirdApproval=request(h,thirdPath,"ConfirmReviewer");d.put("version",1);policy.put("reauthenticate",false);assertEquals(200,h.json("POST",ConfigurationAcceptance.API+"?dry_run=false",bundle,auth("admin")).statusCode());assertEquals(409,h.json("POST",thirdPath+"/"+thirdApproval+"/decision",body,auth("ConfirmReviewer")).statusCode());String fourth=create(h,table),fourthPath="/api/openservice/records/"+table+"/"+fourth+"/approvals",fourthApproval=request(h,fourthPath,"ConfirmReviewer");body.remove("current_password");var unconfirmed=h.json("POST",fourthPath+"/"+fourthApproval+"/decision",body,auth("ConfirmReviewer"));assertEquals(200,unconfirmed.statusCode());assertEquals(false,object(parsed(unconfirmed).get("result")).get("requires_reauthentication"));
   for(int i=0;i<6;i++){try(var db=h.store.open()){var actor=db.one("SELECT * FROM os_user WHERE name='LimitedConfirmReviewer'");db.viewerId=actor.get("user_id").toString();db.viewerRole="agent";var failure=assertThrows(Failure.class,()->Approvals.decide(db,table,fourth,fourthApproval,actor,map("decision","approved","comment","","current_password","wrong verification password")));assertEquals(i<5?400:429,failure.status);}}
   new Store(h.environment);try(var db=h.store.open()){assertEquals(5,db.count("SELECT COUNT(*) FROM os_auth_event WHERE mechanism='approval-review' AND user_name='LimitedConfirmReviewer' AND outcome='failed'"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_auth_event WHERE mechanism='approval-review' AND user_name='LimitedConfirmReviewer' AND outcome='limited'"));}
  }finally{try(var db=h.store.open()){db.update("DELETE FROM os_record WHERE \"table\"=?",table);db.update("DELETE FROM os_schema WHERE name=?",table);db.connection.commit();}}
 }
}
